import { useState, useEffect, useCallback } from 'react';

import { useEventListener } from '../lib/events';
import { supabase } from '../lib/supabase/client';
import type { Article, Project, ContentRow } from '../types/common';
import { transformArticle, transformProject } from '../utils/content';
import { normalizeTag } from '../utils/tagUtils';

interface FilteredContent {
  articles: Article[];
  projects: Project[];
  isLoading: boolean;
  error: Error | null;
}

export function useFilteredContent(
  selectedTags: string[] = [],
  excludeId?: string
): FilteredContent {
  const [content, setContent] = useState<FilteredContent>({
    articles: [],
    projects: [],
    isLoading: false,
    error: null,
  });

  // Listen for content updates via typed event bus
  const handleContentUpdate = useCallback(
    (detail: { type: string; new: Record<string, unknown>; old: Record<string, unknown> }) => {
      console.log('Content updated:', detail);
    },
    []
  );

  const handleTagsUpdate = useCallback(
    (detail: { type: string; new: Record<string, unknown>; old: Record<string, unknown> }) => {
      console.log('Tags updated:', detail);
    },
    []
  );

  useEventListener('content-updated', handleContentUpdate);
  useEventListener('tags-updated', handleTagsUpdate);

  useEffect(() => {
    let isMounted = true;
    const abortController = new AbortController();

    async function fetchContent() {
      try {
        setContent(prev => ({ ...prev, isLoading: true }));

        const { data, error } = await supabase
          .from('content')
          .select('*')
          .eq('published', true)
          .order('priority', { ascending: true })
          .order('date', { ascending: false })
          .abortSignal(abortController.signal);

        // Check if component is still mounted
        if (!isMounted) return;

        if (error) {
          // Ignore abort errors as they're expected when navigating away
          if (error.message?.includes('abort')) {
            return;
          }
          throw error;
        }

        // Filter content based on tags and exclusions
        const filteredContent = (data || []).filter((item: ContentRow) => {
          // Exclude specific content if ID provided
          if (
            excludeId &&
            (item.id === excludeId ||
              item.id === `article_${excludeId}` ||
              item.id === `project_${excludeId}`)
          ) {
            return false;
          }

          // Filter by tags if any selected
          if (!selectedTags.length) return true;

          const itemTags = item.tags || [];
          return selectedTags.some((selectedTag: string) =>
            itemTags.some((tag: string) => normalizeTag(tag) === selectedTag)
          );
        });

        // Transform articles using shared transform function
        const articles = filteredContent
          .filter((item: ContentRow) => item.type === 'article')
          .map(transformArticle);

        // Transform projects using shared transform function
        const projects = filteredContent
          .filter((item: ContentRow) => item.type === 'project')
          .map(transformProject);

        if (isMounted) {
          setContent({
            articles,
            projects,
            isLoading: false,
            error: null,
          });
        }
      } catch (err) {
        if (!isMounted) return;

        // Ignore abort errors
        if (err instanceof Error && err.name === 'AbortError') {
          return;
        }

        console.error('Error fetching filtered content:', err);
        setContent({
          articles: [],
          projects: [],
          isLoading: false,
          error: err instanceof Error ? err : new Error('Failed to fetch content'),
        });
      }
    }

    fetchContent();

    return () => {
      isMounted = false;
      abortController.abort();
    };
  }, [selectedTags.join(','), excludeId]);

  return content;
}
