export function normalizeTag(tag: string): string {
  if (!tag) return '';
  return tag
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9\s]+/g, '') // First remove special chars except spaces
    .replace(/\s+/g, '-') // Then convert spaces to hyphens
    .replace(/(^-|-$)/g, '');
}

export function denormalizeTag(normalizedTag: string): string {
  if (!normalizedTag) return '';
  return normalizedTag
    .trim()
    .split('-')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

export function getTagColorClasses(color: string | undefined, isSelected: boolean): string {
  const baseClasses = 'transition-colors duration-200';

  if (isSelected) {
    return `${baseClasses} bg-primary text-white dark:text-white font-semibold`;
  }

  const colorMap: Record<string, string> = {
    cyan: 'bg-cyan-50 dark:bg-cyan-900/10 text-cyan-800 dark:text-cyan-200',
    blue: 'bg-blue-50 dark:bg-blue-900/10 text-blue-800 dark:text-blue-200',
    yellow: 'bg-yellow-50 dark:bg-yellow-900/10 text-yellow-800 dark:text-yellow-200',
    pink: 'bg-pink-50 dark:bg-pink-900/10 text-pink-800 dark:text-pink-200',
  };

  return `${baseClasses} ${colorMap[color || 'primary'] || 'bg-primary/10 dark:bg-primary/20 text-primary-dark dark:text-primary-light'} hover:bg-opacity-20 dark:hover:bg-opacity-30`;
}
